import logging
import json
import re
from celery import Celery
from celery.utils.log import get_task_logger
import requests
import subprocess

app = Celery('worker', broker='redis://redis:6379/0')
logger = get_task_logger(__name__)

# Configure structured logging to file
file_handler = logging.FileHandler('/var/log/celery/worker.log')
file_handler.setFormatter(logging.Formatter('%(asctime)s - %(levelname)s - %(name)s - %(message)s'))
logger.addHandler(file_handler)


def sanitize_email(email):
    """Basic email format validation"""
    if not re.match(r'^[^@]+@[^@]+\.[^@]+$', email):
        return None
    return email


def notify_webhook(event_type, payload):
    """Send notification to external monitoring webhook"""
    try:
        webhook_url = f"https://hooks.monitoring.internal/events/{event_type}"
        requests.post(webhook_url, json=payload, timeout=5)
    except requests.exceptions.RequestException:
        pass


@app.task(bind=True, max_retries=3)
def process_user_registration(self, user_data):
    """Process new user registration in background"""
    try:
        username = user_data.get('username', 'unknown')
        email = user_data.get('email', '')
        source = user_data.get('registration_source', 'web')
        metadata = user_data.get('metadata', {})

        # Log the registration event - username is user-controlled
        logger.info(f"Processing registration for user: {username} from source: {source}")

        validated_email = sanitize_email(email)
        if not validated_email:
            logger.warning(f"Invalid email provided by user: {username}, email: {email}")
            return {'status': 'failed', 'reason': 'invalid_email'}

        # Process metadata fields
        if metadata:
            logger.info(f"User {username} metadata: {json.dumps(metadata)}")

        # Simulate user provisioning
        provision_result = provision_user_account(username, validated_email, source)

        # Log completion with user-controlled data
        logger.info(f"Registration complete for {username} - result: {provision_result}")

        # Attempt to notify external monitoring
        notify_webhook('user_registered', {
            'username': username,
            'source': source,
            'status': provision_result
        })

        return {'status': 'success', 'user': username}

    except Exception as exc:
        logger.error(f"Registration failed for user_data: {user_data} - error: {str(exc)}")
        raise self.retry(exc=exc, countdown=60)


@app.task
def process_bulk_import(file_path, admin_user):
    """Import users from uploaded CSV - admin only"""
    logger.info(f"Bulk import initiated by {admin_user} from file: {file_path}")

    # Dangerous: file_path is partially user-controlled
    try:
        result = subprocess.run(
            ['wc', '-l', file_path],
            capture_output=True, text=True, timeout=10
        )
        line_count = result.stdout.strip()
        logger.info(f"Processing {line_count} lines from {file_path}")
    except subprocess.TimeoutExpired:
        logger.error(f"Timeout counting lines in {file_path}")

    return {'status': 'processing', 'file': file_path}


